&lt;p style="margin-left:48px"&gt;&lt;span style="font-size:14px"&gt;&lt;strong&gt;Fact:&lt;/strong&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt; Pacific Power customer service employees &lt;/span&gt;&lt;strong&gt;will always&lt;/strong&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt; have your correct account number.&lt;/span&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW242206867 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; clear: both; cursor: text; overflow: visible; position: relative; direction: ltr;"&gt;
&lt;p&gt;&lt;span style="font-size:14px"&gt;&lt;span style="font-family:calibri,calibri_embeddedfont,calibri_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
